package com.zpantry.todaymenu.service;
import com.zpantry.ingredient.persistence.IngredientRepository; import com.zpantry.recipe.persistence.*; import com.zpantry.todaymenu.api.DailyNutritionResponse; import com.zpantry.todaymenu.persistence.CookingLogRepository; import com.zpantry.todaymenu.persistence.TodayMenuItemRepository; import com.zpantry.user.persistence.UserProfileRepository; import java.math.*; import java.time.*; import java.util.UUID; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class DailyNutritionService { private final CookingLogRepository logs; private final TodayMenuItemRepository menus; private final RecipeRepository recipes; private final RecipeIngredientRepository links; private final IngredientRepository ingredients; private final UserProfileRepository profiles; public DailyNutritionService(CookingLogRepository l,TodayMenuItemRepository m,RecipeRepository r,RecipeIngredientRepository x,IngredientRepository i,UserProfileRepository p){logs=l;menus=m;recipes=r;links=x;ingredients=i;profiles=p;}
 @Transactional(readOnly=true) public DailyNutritionResponse daily(UUID user,LocalDate date){LocalDate d=date==null?LocalDate.now(ZoneId.of("Asia/Ho_Chi_Minh")):date;BigDecimal consumed=logs.findAllByUserIdAndDeletedFalse(user,org.springframework.data.domain.Pageable.unpaged()).stream().filter(l->l.cookedAt!=null&&l.cookedAt.atZone(ZoneId.of("Asia/Ho_Chi_Minh")).toLocalDate().equals(d)).map(this::calories).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal target=profiles.findByUserIdAndDeletedFalse(user).map(p->p.getDailyCalorieTarget()).orElse(null);return new DailyNutritionResponse(d,target,consumed.setScale(0,RoundingMode.HALF_UP),target==null?null:target.subtract(consumed).setScale(0,RoundingMode.HALF_UP));}
 private BigDecimal calories(com.zpantry.todaymenu.domain.CookingLogEntity log){if(log.recipeId==null)return BigDecimal.ZERO;var recipe=recipes.findByIdAndDeletedFalse(log.recipeId).orElse(null);if(recipe==null)return BigDecimal.ZERO;BigDecimal ratio=menus.findById(log.todayMenuItemId).filter(m->m.servingSize!=null&&recipe.servingSize!=null&&recipe.servingSize>0).map(m->BigDecimal.valueOf(m.servingSize).divide(BigDecimal.valueOf(recipe.servingSize),4,RoundingMode.HALF_UP)).orElse(BigDecimal.ONE);return links.findAllByRecipeIdAndDeletedFalse(recipe.getId()).stream().map(x->ingredients.findByIdAndDeletedFalse(x.ingredientId).map(i->i.caloriesPerUnit==null||x.quantity==null?BigDecimal.ZERO:i.caloriesPerUnit.multiply(x.quantity).multiply(ratio)).orElse(BigDecimal.ZERO)).reduce(BigDecimal.ZERO,BigDecimal::add);}
}
